cd /tmp/sv-b557a116fda44a2b83d7d6c8f3218e38/simple-solution && dotnet package list --format json 2>/dev/null | python3 -c "import sys; open('after-cpm-packages.json','w').write(sys.stdin.read())" && python3 -c "
import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))

def get_pkgs(data):
    pkgs = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                pkgs[(name, pkg['id'])] = pkg['resolvedVersion']
    return pkgs

bp = get_pkgs(b)
ap = get_pkgs(a)
if bp == ap:
    print('✅ All package versions match baseline exactly.')
else:
    for k in set(list(bp.keys()) + list(ap.keys())):
        if bp.get(k) != ap.get(k):
            print(f'  DIFF: {k}: {bp.get(k)} -> {ap.get(k)}')
"

